#!/usr/bin/env bash
# AKFC — Demandes (tickets), incrément 2 : back-end du formulaire de contact (sans écran).
#  - router tRPC « ticket » : categories (public) + submit (public)
#      · membre connecté : identité ET adresse du compte (l'adresse saisie est ignorée)
#      · visiteur : adresse obligatoire, nom conseillé
#      · champ piège « website » (robots) ; 5 envois / heure max par IP et par adresse
#  - e-mails envoyés par noreply@ : accusé de réception au demandeur ([AKFC-0042], délai promis,
#    copie du message, Reply-To = adresse de la catégorie) + avis au club (adresse de la catégorie,
#    Reply-To = demandeur). Un échec d'envoi n'annule pas la demande (journalisé).
#  - schéma Zod partagé : packages/contracts/src/tickets/ticket.schema.ts
#  Aucune migration. Preuve avant commit : pnpm check (sinon TOUT est restauré).
# Usage : bash apply-tickets-increment2.sh   (AKFC_APPLY_ONLY=1 : applique sans vérifier ni committer)
set -euo pipefail
[ -f "package.json" ] || { echo "ERREUR: racine du repo." >&2; exit 1; }
MOD="packages/backend/src/modules/tickets"
[ -f "$MOD/tickets.service.ts" ] || { echo "ERREUR: applique d'abord apply-tickets-increment1.sh." >&2; exit 1; }
[ -f "$MOD/router.ts" ] && { echo "— déjà appliqué"; exit 0; }

IDX="packages/backend/src/modules/index.ts"
NEW=("$MOD/router.ts" "$MOD/submitThrottle.ts" packages/backend/src/email/services/sendTicketEmails.ts packages/contracts/src/tickets/ticket.schema.ts)
for f in "${NEW[@]}"; do [ -e "$f" ] && { echo "ERREUR: $f existe déjà." >&2; exit 1; }; done
BK=/tmp/akfc_tk2_backup; rm -rf "$BK"; mkdir -p "$BK"; cp "$IDX" "$BK/index.ts"
restore(){ cp "$BK/index.ts" "$IDX"; rm -f "${NEW[@]}"; rmdir packages/contracts/src/tickets 2>/dev/null || true; echo "↩ fichiers restaurés à l'identique (aucun commit)."; }

W=/tmp/akfc_tk2; rm -rf "$W"; mkdir -p "$W"
echo '' | base64 -d > "$W/index_edit.py"
echo '' | base64 -d > "$W/router.ts"
echo '' | base64 -d > "$W/submitThrottle.ts"
echo '' | base64 -d > "$W/sendTicketEmails.ts"
echo '' | base64 -d > "$W/ticket.schema.ts"

echo "== application =="
cp "$W/router.ts" "$W/submitThrottle.ts" "$MOD/"
cp "$W/sendTicketEmails.ts" packages/backend/src/email/services/
mkdir -p packages/contracts/src/tickets && cp "$W/ticket.schema.ts" packages/contracts/src/tickets/
echo "  ok  4 fichiers créés"
python3 "$W/index_edit.py" . || { restore; exit 1; }

if [ "${AKFC_APPLY_ONLY:-0}" = "1" ]; then echo "APPLY_ONLY"; exit 0; fi

echo "== pnpm check =="
if ! pnpm check > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"; grep -nE "conventions Next|error TS|Error:" /tmp/akfc_tc.log | head -15; restore; exit 1
fi
echo "  ✅ check OK"

git add "$IDX" "${NEW[@]}"
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
feat(tickets): envoi d'une demande (router ticket, accusé de réception, avis au club)

